CREATE FUNCTION public.security_department_read(p_department text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_approved_user(auth.uid()) AND (public.has_role(auth.uid(),'super_admin') OR public.has_department_permission(auth.uid(),p_department,'view')) $$;
CREATE FUNCTION public.security_issue_read(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.goods_issue_pending h WHERE h.id=p_id AND public.is_approved_user(auth.uid()) AND (h.created_by=auth.uid() OR public.security_department_read(h.requester_department))) $$;
CREATE FUNCTION public.security_asset_read(p_equipment uuid,p_media_player uuid,p_tool uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_approved_user(auth.uid()) AND (public.has_role(auth.uid(),'super_admin') OR EXISTS (SELECT 1 FROM public.equipment e WHERE e.id=p_equipment AND public.security_department_read(e.department)) OR EXISTS (SELECT 1 FROM public.media_players m WHERE m.id=p_media_player AND public.security_department_read(m.department)) OR EXISTS (SELECT 1 FROM public.tools t WHERE t.id=p_tool AND public.security_department_read(t.department)) OR EXISTS (SELECT 1 FROM public.goods_issue_pending_items i JOIN public.goods_issue_pending h ON h.id=i.pending_id WHERE ((p_equipment IS NOT NULL AND i.equipment_id=p_equipment) OR (p_media_player IS NOT NULL AND i.media_player_id=p_media_player)) AND (h.created_by=auth.uid() OR public.security_department_read(h.requester_department)))) $$;
REVOKE ALL ON FUNCTION public.security_department_read(text),public.security_issue_read(uuid),public.security_asset_read(uuid,uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.security_department_read(text),public.security_issue_read(uuid),public.security_asset_read(uuid,uuid,uuid) TO authenticated;
DO $changes$ DECLARE t text; pred text; p record; BEGIN
FOREACH t IN ARRAY ARRAY['delivery_confirmations','stock_location_allocations','repair_actions','goods_issue','media_player_models','media_sites','equipment_pm_history','equipment_billboard_compatibility','media_player_statuses','media_player_billboard_history','warehouses','billboards','purchase_requests','units','equipment_transfers','direct_shipment_items','billboard_package_items','pm_results','companies','equipment_pm_schedules','billboard_pm_actions','equipment_pm_tasks','billboard_pm_history','mp_claim_results','goods_issue_pending_items','issue_good_returns','technician_tools','billboard_packages','claim_progress_logs','equipment_pm_task_images','media_players','defective_returns','claim_records','tool_pm_history','zones','departments','pm_schedules','stock_movements','media_player_serial_history','media_player_images','mp_assessment_results','media_player_specifications','equipment_compatibility_packages','tool_documents','billboard_equipment_history','pm_history','equipment','tools','media_player_names','equipment_serial_numbers','tool_images'] LOOP
pred:=CASE
WHEN t IN ('equipment','media_players','tools','billboards') THEN format('public.security_department_read(%I.department)',t)
WHEN t IN ('repair_actions','media_sites','units','pm_results','mp_claim_results','mp_assessment_results','media_player_specifications','media_player_names','billboard_packages','media_player_models','media_player_statuses','departments') THEN 'public.is_approved_user(auth.uid())'
WHEN t='warehouses' THEN 'public.security_department_read(warehouses.department) OR EXISTS(SELECT 1 FROM unnest(warehouses.departments) dep WHERE public.security_department_read(dep))'
WHEN t='companies' THEN 'EXISTS(SELECT 1 FROM public.departments d WHERE d.id=companies.department_id AND public.security_department_read(d.name))'
WHEN t='zones' THEN 'EXISTS(SELECT 1 FROM public.warehouses w WHERE w.id=zones.warehouse_id)'
WHEN t='stock_location_allocations' THEN 'public.security_asset_read(stock_location_allocations.equipment_id,stock_location_allocations.media_player_id,stock_location_allocations.tool_id) OR EXISTS(SELECT 1 FROM public.warehouses w WHERE w.id=stock_location_allocations.warehouse_id)'
WHEN t IN ('purchase_requests','equipment_transfers','equipment_serial_numbers','equipment_billboard_compatibility','equipment_compatibility_packages') THEN format('public.security_asset_read(%I.equipment_id,NULL::uuid,NULL::uuid)',t)
WHEN t='goods_issue' THEN 'EXISTS(SELECT 1 FROM public.goods_issue_pending h WHERE h.document_no=goods_issue.document_no AND public.security_issue_read(h.id)) OR (NOT EXISTS(SELECT 1 FROM public.goods_issue_pending h WHERE h.document_no=goods_issue.document_no) AND public.security_asset_read(goods_issue.equipment_id,NULL::uuid,NULL::uuid))'
WHEN t='goods_issue_pending_items' THEN 'public.security_issue_read(goods_issue_pending_items.pending_id)'
WHEN t='issue_good_returns' THEN 'public.security_issue_read(issue_good_returns.pending_id) OR public.security_department_read(issue_good_returns.department) OR public.security_asset_read(issue_good_returns.equipment_id,issue_good_returns.media_player_id,NULL::uuid)'
WHEN t='delivery_confirmations' THEN 'public.security_issue_read(delivery_confirmations.goods_issue_pending_id) OR EXISTS(SELECT 1 FROM public.direct_shipments ds WHERE ds.id=delivery_confirmations.direct_shipment_id AND (public.security_department_read(ds.department) OR ds.created_by=auth.uid()))'
WHEN t='direct_shipment_items' THEN 'EXISTS(SELECT 1 FROM public.direct_shipments ds WHERE ds.id=direct_shipment_items.direct_shipment_id AND (public.security_department_read(ds.department) OR ds.created_by=auth.uid()))'
WHEN t IN ('media_player_billboard_history','media_player_images','media_player_serial_history') THEN format('public.security_asset_read(NULL::uuid,%I.media_player_id,NULL::uuid)',t)
WHEN t='billboard_equipment_history' THEN 'public.security_asset_read(billboard_equipment_history.equipment_id,NULL::uuid,NULL::uuid) OR EXISTS(SELECT 1 FROM public.billboards b WHERE b.id=billboard_equipment_history.billboard_id AND public.security_department_read(b.department))'
WHEN t IN ('billboard_pm_actions','billboard_pm_history','pm_schedules','billboard_package_items') THEN format('EXISTS(SELECT 1 FROM public.billboards b WHERE b.id=%I.billboard_id AND public.security_department_read(b.department))',t)
WHEN t='pm_history' THEN 'EXISTS(SELECT 1 FROM public.pm_schedules s WHERE s.id=pm_history.pm_schedule_id)'
WHEN t='equipment_pm_schedules' THEN 'public.security_department_read(equipment_pm_schedules.department) OR public.security_asset_read(equipment_pm_schedules.equipment_id,NULL::uuid,NULL::uuid)'
WHEN t IN ('equipment_pm_tasks','equipment_pm_history') THEN format('EXISTS(SELECT 1 FROM public.equipment_pm_schedules s WHERE s.id=%I.equipment_pm_schedule_id)',t)
WHEN t='equipment_pm_task_images' THEN 'EXISTS(SELECT 1 FROM public.equipment_pm_tasks t WHERE t.id=equipment_pm_task_images.equipment_pm_task_id)'
WHEN t IN ('tool_documents','tool_images','tool_pm_history','technician_tools') THEN format('public.security_asset_read(NULL::uuid,NULL::uuid,%I.tool_id)',t)
WHEN t='claim_records' THEN 'public.security_asset_read(claim_records.equipment_id,claim_records.media_player_id,NULL::uuid)'
WHEN t='claim_progress_logs' THEN 'EXISTS(SELECT 1 FROM public.claim_records c WHERE c.id=claim_progress_logs.claim_record_id)'
WHEN t='defective_returns' THEN 'public.security_asset_read(defective_returns.equipment_id,defective_returns.media_player_id,NULL::uuid) OR public.security_department_read(defective_returns.reporter_department) OR public.security_issue_read((SELECT i.pending_id FROM public.goods_issue_pending_items i WHERE i.id=defective_returns.source_issue_item_id))'
WHEN t='stock_movements' THEN 'public.security_asset_read(stock_movements.equipment_id,stock_movements.equipment_id,stock_movements.equipment_id) OR EXISTS(SELECT 1 FROM public.goods_issue_pending h WHERE h.document_no=stock_movements.reference_document AND public.security_issue_read(h.id))'
ELSE NULL END;
IF pred IS NULL THEN RAISE EXCEPTION 'Missing selected-table predicate: %',t; END IF;
pred:='public.is_approved_user(auth.uid()) AND ('||pred||')';
FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=t AND cmd='SELECT' AND qual='true' LOOP EXECUTE format('ALTER POLICY %I ON public.%I TO authenticated USING (%s)',p.policyname,t,pred); END LOOP;
EXECUTE format('CREATE POLICY security_selected_read_boundary ON public.%I AS RESTRICTIVE FOR SELECT TO authenticated USING (%s)',t,pred);
END LOOP; END $changes$;
CREATE POLICY security_selected_no_anon_enumeration ON public.media_player_models AS RESTRICTIVE FOR SELECT TO anon USING(false);
CREATE POLICY security_selected_no_anon_enumeration ON public.media_player_statuses AS RESTRICTIVE FOR SELECT TO anon USING(false);
CREATE POLICY security_selected_no_anon_enumeration ON public.media_player_images AS RESTRICTIVE FOR SELECT TO anon USING(false);
CREATE POLICY security_selected_no_anon_enumeration ON public.tool_images AS RESTRICTIVE FOR SELECT TO anon USING(false);
CREATE POLICY security_selected_no_anon_enumeration ON public.media_players AS RESTRICTIVE FOR SELECT TO anon USING(false);
ALTER POLICY "Authenticated can read tool-documents" ON storage.objects TO authenticated USING(bucket_id='tool-documents' AND public.is_approved_user(auth.uid()) AND (owner_id=auth.uid()::text OR public.has_role(auth.uid(),'super_admin') OR EXISTS(SELECT 1 FROM public.tool_documents d WHERE d.file_path=storage.objects.name)));
ALTER POLICY "Public read tool-images" ON storage.objects TO authenticated USING(bucket_id='tool-images' AND public.is_approved_user(auth.uid()) AND (owner_id=auth.uid()::text OR public.has_role(auth.uid(),'super_admin') OR EXISTS(SELECT 1 FROM public.tool_images i WHERE i.image_url=storage.objects.name)));
CREATE FUNCTION public.public_get_mp_qr_extras(_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('model_name',(SELECT name FROM public.media_player_models WHERE id=m.model_id),'status_label',(SELECT label FROM public.media_player_statuses WHERE value=m.status),'images',coalesce((SELECT jsonb_agg(image_url ORDER BY display_order) FROM public.media_player_images WHERE media_player_id=m.id),'[]'::jsonb)) FROM public.media_players m WHERE m.id=_id $$;
REVOKE ALL ON FUNCTION public.public_get_mp_qr_extras(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_get_mp_qr_extras(uuid) TO anon,authenticated,service_role;